#!/usr/bin/env python3
"""Coordinate the A/B writer and force its independent 9p witnesses."""
# Some portions generated by Codex
import json
import hashlib
import os
from pathlib import Path
import shutil
import subprocess
import time

ROOT = Path(os.environ.get("RDF4J_CRASHLAB_RESULTS_DIR", "/mnt/run-results"))
DATA = Path(os.environ.get("RDF4J_CRASHLAB_DATA_DIR", "/mnt/crash-data/store"))
JAVA = os.environ.get("RDF4J_CRASHLAB_JAVA", "/usr/bin/java")
CLASS_DIR = Path(os.environ["RDF4J_CRASHLAB_CLASS_DIR"])
CP = str(CLASS_DIR) + ":" + (ROOT / "actual-build-classpath-guest.txt").read_text().strip()
SCENARIO = (ROOT / "actual-powercut-scenario.txt").read_text(encoding="utf-8").strip()
MAIN_CLASS = "org.eclipse.rdf4j.sail.lmdb.CrashPowerCutWriterMain"
LOG = ROOT / "actual-powercut-writer-controller.log"
EVENTS = ROOT / "actual-powercut-writer-events.jsonl"
FAIL = ROOT / "actual-powercut-writer-failed"

EXPECTED_CUTPOINTS = {
    "mixed-replay-before-native-commit": "AFTER_FULL_REPLAY_BEFORE_AUTHORITATIVE_COMMIT",
    "dictionary-before-triple-commit": "AFTER_DICTIONARY_COMMIT_BEFORE_TRIPLESTORE_COMMIT",
    "commit-returned-before-ack": "AFTER_CONNECTION_COMMIT_RETURNED_BEFORE_B_ACK",
}
RUNNING_TRIALS = ("running-normal-preflight-write", "running-normal-preflight-persistence",
                  "running-journal-replay-write", "running-journal-replay-persistence")


def fsync_directory(path):
    fd = os.open(path, os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def record(event, **fields):
    row = {"time_ns": time.time_ns(), "event": event, **fields}
    with EVENTS.open("a", encoding="utf-8") as stream:
        stream.write(json.dumps(row, sort_keys=True) + "\n")
        stream.flush()
        os.fsync(stream.fileno())


def force_copy(source, destination):
    if not source.is_file() or source.is_symlink():
        raise FileNotFoundError("missing or unsafe child witness: " + str(source))
    with source.open("rb") as src, destination.open("xb") as dst:
        shutil.copyfileobj(src, dst)
        dst.flush()
        os.fsync(dst.fileno())
    fsync_directory(destination.parent)
    if source.read_bytes() != destination.read_bytes():
        raise IOError("host/9p witness copy differs from exact child payload")


def write_exclusive(path, value):
    with path.open("x", encoding="utf-8") as stream:
        stream.write(json.dumps(value, indent=2, sort_keys=True) + "\n")
        stream.flush()
        os.fsync(stream.fileno())
    fsync_directory(path.parent)


def fail(message, child=None):
    with LOG.open("a", encoding="utf-8") as stream:
        stream.write("FAIL: " + message + "\n")
        stream.flush()
        os.fsync(stream.fileno())
    record("FAIL", message=message)
    with FAIL.open("x", encoding="utf-8") as stream:
        stream.write(message + "\n")
        stream.flush()
        os.fsync(stream.fileno())
    fsync_directory(FAIL.parent)
    if child is not None and child.poll() is None:
        child.kill()
        child.wait(timeout=10)


def send(child, command):
    if child.stdin is None:
        raise RuntimeError("writer child has no control input")
    child.stdin.write(command + "\n")
    child.stdin.flush()


def next_event(child, log):
    line = child.stdout.readline()
    log.write("child=" + line)
    log.flush()
    if not line:
        raise RuntimeError("writer child exited before cutpoint; exit=" + str(child.poll()))
    normalized = line.strip().removeprefix("CRASHLAB:")
    if not normalized:
        return None
    if not line.startswith("CRASHLAB:"):
        return None
    return normalized


def main():
    if SCENARIO not in EXPECTED_CUTPOINTS and SCENARIO not in RUNNING_TRIALS:
        raise ValueError("unsupported scenario: " + SCENARIO)
    expected_files = (
        "actual-A-payload-child.tsv", "actual-B-payload-child.tsv",
        "actual-A-ack-witness.tsv", "actual-B-attempt-witness.tsv",
        "actual-A-commit-ack.json", "actual-B-commit-invoked-child.marker",
        "actual-B-commit-invoked-witness.marker", "actual-B-native-commit-returned-child.marker",
        "actual-B-native-commit-returned-witness.marker", "actual-cutpoint-child.marker",
        "actual-cutpoint-child-witness.txt", "actual-cutpoint-witness.json",
        "actual-powercut-writer-controller.log", "actual-powercut-writer-events.jsonl",
        "actual-powercut-writer-failed",
    )
    for name in expected_files:
        path = ROOT / name
        if path.exists() or path.is_symlink():
            raise FileExistsError("refusing preexisting power-cut artifact: " + str(path))
    if (ROOT / "actual-B-acknowledged-witness.tsv").exists():
        raise FileExistsError("B acknowledgment must not exist before the power-cut writer starts")
    with LOG.open("x", encoding="utf-8", buffering=1) as log, EVENTS.open("x", encoding="utf-8"):
        command = [JAVA, "-cp", CP, MAIN_CLASS, str(DATA), SCENARIO]
        log.write("writer_command=" + json.dumps(command) + "\n")
        child = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                 stderr=subprocess.STDOUT, text=True, bufsize=1)
        record("WRITER_CHILD_STARTED", pid=child.pid, scenario=SCENARIO)
        try:
            a_acknowledged = b_attempted = False
            b_commit_invoked = b_commit_returned = cutpoint_reached = False
            while True:
                event = next_event(child, log)
                if event is None:
                    continue
                if event == "A_COMMIT_RETURNED":
                    force_copy(ROOT / "actual-A-payload-child.tsv", ROOT / "actual-A-ack-witness.tsv")
                    write_exclusive(ROOT / "actual-A-commit-ack.json", {
                        "event": "A_COMMIT_RETURNED",
                        "payload": "actual-A-ack-witness.tsv",
                        "payload_bytes": (ROOT / "actual-A-ack-witness.tsv").stat().st_size,
                        "payload_sha256": hashlib.sha256(
                            (ROOT / "actual-A-ack-witness.tsv").read_bytes()).hexdigest(),
                    })
                    a_acknowledged = True
                    record("A_ACK_WITNESS_FSYNCED", payload="actual-A-ack-witness.tsv")
                    send(child, "CONTINUE_AFTER_A_ACK")
                    if SCENARIO in RUNNING_TRIALS:
                        # No further commands, payload-copy barriers, or per-generation stdout protocol.
                        for line in child.stdout:
                            log.write("child=" + line)
                        code = child.wait()
                        write_exclusive(ROOT / "actual-running-child-exited.json", {"trial": SCENARIO, "exit": code})
                        raise RuntimeError("continuous writer exited before its guest was killed: " + str(code))
                elif event == "B_ATTEMPT_FSYNCED":
                    if not a_acknowledged:
                        raise RuntimeError("B payload appeared before acknowledged A witness")
                    force_copy(ROOT / "actual-B-payload-child.tsv", ROOT / "actual-B-attempt-witness.tsv")
                    b_attempted = True
                    record("B_ATTEMPT_WITNESS_FSYNCED", payload="actual-B-attempt-witness.tsv")
                    send(child, "CONTINUE_AFTER_B_WITNESS")
                elif event == "B_NATIVE_COMMIT_RETURNED":
                    if SCENARIO != "commit-returned-before-ack":
                        raise RuntimeError("native commit returned before the requested pre-publication cut")
                    force_copy(ROOT / "actual-B-commit-invoked-child.marker",
                               ROOT / "actual-B-commit-invoked-witness.marker")
                    force_copy(ROOT / "actual-B-native-commit-returned-child.marker",
                               ROOT / "actual-B-native-commit-returned-witness.marker")
                    b_commit_invoked = True
                    b_commit_returned = True
                    record("B_COMMIT_INVOKED_WITNESS_FSYNCED")
                    record("B_NATIVE_COMMIT_RETURNED_WITNESS_FSYNCED")
                elif event.startswith("CUTPOINT_REACHED:"):
                    cutpoint = event.split(":", 1)[1]
                    if cutpoint != EXPECTED_CUTPOINTS[SCENARIO]:
                        raise RuntimeError("unexpected cutpoint " + cutpoint + " for " + SCENARIO)
                    if not b_commit_invoked and (ROOT / "actual-B-commit-invoked-child.marker").is_file():
                        force_copy(ROOT / "actual-B-commit-invoked-child.marker",
                                   ROOT / "actual-B-commit-invoked-witness.marker")
                        b_commit_invoked = True
                        record("B_COMMIT_INVOKED_WITNESS_FSYNCED")
                    if (not b_commit_returned
                            and (ROOT / "actual-B-native-commit-returned-child.marker").is_file()):
                        force_copy(ROOT / "actual-B-native-commit-returned-child.marker",
                                   ROOT / "actual-B-native-commit-returned-witness.marker")
                        b_commit_returned = True
                        record("B_NATIVE_COMMIT_RETURNED_WITNESS_FSYNCED")
                    force_copy(ROOT / "actual-cutpoint-child.marker", ROOT / "actual-cutpoint-child-witness.txt")
                    expected_invoked = True
                    expected_returned = SCENARIO == "commit-returned-before-ack"
                    if not (a_acknowledged and b_attempted):
                        raise RuntimeError("cutpoint arrived before both exact A and B witness payloads")
                    if b_commit_invoked != expected_invoked or b_commit_returned != expected_returned:
                        raise RuntimeError("commit-boundary witness markers do not match cutpoint contract")
                    if (ROOT / "actual-B-acknowledged-witness.tsv").exists():
                        raise RuntimeError("B must remain unacknowledged at every cutpoint")
                    write_exclusive(ROOT / "actual-cutpoint-witness.json", {
                        "scenario": SCENARIO,
                        "cutpoint": cutpoint,
                        "A_acknowledged": True,
                        "B_attempted": True,
                        "B_commit_invoked": b_commit_invoked,
                        "B_native_commit_returned": b_commit_returned,
                        "B_acknowledged": False,
                    })
                    record("CUTPOINT_WITNESS_FSYNCED", cutpoint=cutpoint,
                           b_commit_invoked=b_commit_invoked, b_native_commit_returned=b_commit_returned)
                    cutpoint_reached = True
                    log.write("controller_blocked_until_host_cuts_qemu\n")
                    log.flush()
                    os.fsync(log.fileno())
                    while True:
                        time.sleep(1)
                else:
                    raise RuntimeError("unexpected power-cut writer event: " + event)
        except BaseException as error:
            fail(type(error).__name__ + ": " + str(error), child)
            raise
        finally:
            if not cutpoint_reached and child.poll() is None:
                child.kill()
                child.wait(timeout=10)


if __name__ == "__main__":
    main()
